import type { League } from './types';
import catalog from './catalog.json';

export interface TeamConfig {
  key: string; // "nfl-pit"; used in URLs and storage
  league: League;
  name: string;
  short: string;
  abbr: string; // display abbreviation (ESPN's)
  /** Source identifiers. */
  espn?: { sport: string; league: string; abbr: string };
  nhl?: { abbr: string };
  mlb?: { teamId: number };
  primary: string;
  secondary: string;
  logo?: string;
  logoDark?: string;
}

/** Every NFL, NBA, NHL and MLB team (generated by scripts/build-catalog.mjs). */
export const CATALOG = catalog as TeamConfig[];

export const LEAGUES: { id: League; name: string }[] = [
  { id: 'nfl', name: 'NFL' },
  { id: 'nhl', name: 'NHL' },
  { id: 'nba', name: 'NBA' },
  { id: 'mlb', name: 'MLB' },
];

export const DEFAULT_FAVORITES = ['nfl-pit', 'nhl-pit', 'nba-cle', 'mlb-cle'];

/** Keys used before favorites existed, so old links keep working. */
const LEGACY: Record<string, string> = {
  steelers: 'nfl-pit',
  penguins: 'nhl-pit',
  cavaliers: 'nba-cle',
  guardians: 'mlb-cle',
};

export const teamByKey = (key: string) => CATALOG.find((t) => t.key === (LEGACY[key] ?? key));

/** Abbreviations a feed may use for this team (ESPN's and the league's own). */
export const abbrsOf = (t: TeamConfig) => new Set([t.abbr, t.nhl?.abbr].filter(Boolean) as string[]);

function luminance(hex: string) {
  const n = parseInt(hex.replace('#', ''), 16);
  const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((c) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/**
 * The team color to use for accents. Black or white primaries (Steelers, Penguins) disappear on
 * dark or light backgrounds, so those use the secondary color instead.
 */
export function accentOf(t: TeamConfig): string {
  const l = luminance(t.primary);
  return l < 0.02 || l > 0.85 ? t.secondary : t.primary;
}

// ---------- favorites ----------

const FAV_KEY = 'scores.favorites.v1';

export function loadFavorites(): string[] {
  try {
    const raw = localStorage.getItem(FAV_KEY);
    if (raw) {
      return (JSON.parse(raw) as string[]).map((k) => teamByKey(k)?.key).filter(Boolean) as string[];
    }
  } catch {
    /* ignore */
  }
  return DEFAULT_FAVORITES;
}

export function saveFavorites(keys: string[]) {
  try {
    localStorage.setItem(FAV_KEY, JSON.stringify(keys));
  } catch {
    /* ignore */
  }
  window.dispatchEvent(new Event('favorites-changed'));
}

/** CSS variables for a team's colors. */
export function teamStyle(t: TeamConfig): Record<string, string> {
  const accent = accentOf(t);
  return { '--team': accent, '--team2': accent === t.primary ? t.secondary : t.primary };
}
